// EntryRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type EntryRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Entry) error
}

// EntryRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type EntryRetrievalObserver = lifecycle.Observer[Entry, EntryRetrievalHooks]

// NewEntryRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewEntryRetrievalObserver(observer string) EntryRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Entry, EntryRetrievalHooks](observer)
}

// RegisterEntryRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterEntryRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer EntryRetrievalObserver, construct func(foundation.Resolver) (func() EntryRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (EntryRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Entry], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Entry, EntryRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	var allHooks []EntryRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Entry]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	return foundryquery.RetrievalHooks[Entry]{Retrieved: func(ctx context.Context, executor database.Executor, item Entry) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// EntryAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type EntryAuditPolicy struct {
	_ [0]*Entry
	// ID controls the audit representation of stored vault_entries.id.
	ID record.Disclosure
	// Label controls the audit representation of stored vault_entries.label.
	Label record.Disclosure
	// Token controls the audit representation of stored vault_entries.token.
	Token record.Disclosure
	// Settings controls the audit representation of stored vault_entries.settings.
	Settings record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes EntryChanges) Audit(policy EntryAuditPolicy) (record.Model[Entry, model.ID[Entry]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Entry, model.ID[Entry]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Entry, model.ID[Entry]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Entry](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "label", codec.String[string](), changes.fields.Label, policy.Label); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "token", encrypted.TextCodec(), changes.fields.Token, policy.Token); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	if err = record.Capture(builder, "settings", codec.Nullable(encrypted.JSONCodec[Settings]()), changes.fields.Settings, policy.Settings); err != nil {
		return record.Model[Entry, model.ID[Entry]]{}, err
	}
	return builder.Build()
}

